APCARDS = [
 # ---------- A. Hadices ----------
 dict(id="AP01", key="B6922", tag="Hadiz · Bujari 6922 · Ibn Abbas", specs=["AP-b6922"],
  title="Bujari 6922: «Quien cambie su religión, matadlo» (Ibn Abbas, que lo atribuye al Profeta)",
  ref="al-Bujari, Sahih, Kitab istitabat al-murtaddin, «Bab hukm al-murtadd wa-l-murtadda wa-istitabatihim», n.º 6922",
  ar_ref="صحيح البخاري ٦٩٢٢", site=HU, url="https://hadithunlocked.com/bukhari:6922",
  es=["Nos contó Abu l-Nuʿman Muhammad ibn al-Fadl: nos contó Hammad ibn Zayd, de Ayyub, de ʿIkrima, que dijo: Le trajeron a ʿAli unos zanadiqa [herejes encubiertos] y los quemó. Eso llegó a Ibn Abbas y dijo: [[a:«Yo no los habría quemado, por la prohibición del Mensajero de Dios ﷺ,]] [[k:y los habría matado, por el dicho del Mensajero de Dios ﷺ: ‹Quien cambie su religión, matadlo›»]]."],
  prueba="Es el texto base más citado para la pena de muerte del apóstata: Ibn Abbas atribuye al Profeta la orden «quien cambie su religión, matadlo», y al-Bujari lo recoge, con cadena completa, bajo el capítulo «El juicio del apóstata y de la apóstata y pedirles que se arrepientan».",
  ojo="Es una sola cadena (ʿIkrima, cliente de Ibn Abbas → Ibn Abbas); el mismo relato está en 3017 por otra ruta hasta ʿIkrima (AP02), así que no son dos hadices independientes. Lo que Ibn Abbas objeta a ʿAli es quemar, no matar. El texto no dice nada de arrepentimiento previo, de mujeres, ni si «quien cambie su religión» alcanza a quien nunca fue musulmán: eso lo discuten los juristas (tarjetas siguientes). El contexto es un caso de «zanadiqa», grupo cuya identidad discuten los propios comentaristas.", uso=USO),

 dict(id="AP02", key="B3017", tag="Hadiz · Bujari 3017 · misma historia", specs=["AP-b3017"],
  title="Bujari 3017: ʿAli quema a unos hombres; Ibn Abbas: «no castiguéis con el castigo de Dios… y los habría matado: ‹quien cambie su religión, matadlo›»",
  ref="al-Bujari, Sahih, Kitab al-yihad wa-l-siyar, «Bab la yuʿadhdhab bi-ʿadhab Allah», n.º 3017",
  ar_ref="صحيح البخاري ٣٠١٧", site=HU, url="https://hadithunlocked.com/bukhari:3017",
  es=["Nos contó ʿAli ibn ʿAbd Allah: nos contó Sufyan, de Ayyub, de ʿIkrima, que ʿAli quemó a unos hombres. Llegó a Ibn Abbas y dijo: [[a:«Yo no los habría quemado, porque el Profeta ﷺ dijo: ‹No castiguéis con el castigo de Dios›;]] [[k:y los habría matado, como dijo el Profeta ﷺ: ‹Quien cambie su religión, matadlo›»]]."],
  prueba="La misma frase, en el Libro del Yihad, con la prohibición explícita («no castiguéis con el castigo de Dios», es decir, con fuego). Distingue el castigo (la muerte) del modo (no por fuego).",
  ojo="No es un hadiz independiente de AP01: misma cadena desde ʿIkrima, puesta por al-Bujari en dos capítulos. Es una sola frase, atribuida al Profeta por un único Compañero (Ibn Abbas) por un único transmisor (ʿIkrima). Y muestra que entre los Compañeros hubo desacuerdo en el modo: ʿAli quemó, Ibn Abbas habría matado de otra manera.", uso=USO),

 dict(id="AP03", key="B6878", tag="Hadiz · Bujari 6878 · Ibn Masʿud", specs=["AP-b6878"],
  title="Bujari 6878: «No es lícita la sangre de un musulmán… salvo por una de tres: la vida por la vida, el casado adúltero y el que se aparta de la religión, el que abandona la comunidad»",
  ref="al-Bujari, Sahih, Kitab al-diyat, «Bab qawl Allah taʿala: anna l-nafs bi-l-nafs», n.º 6878",
  ar_ref="صحيح البخاري ٦٨٧٨", site=HU, url="https://hadithunlocked.com/bukhari:6878",
  es=["Nos contó ʿUmar ibn Hafs: nos contó mi padre: nos contó al-Aʿmash, de ʿAbd Allah ibn Murra, de Masruq, de ʿAbd Allah [ibn Masʿud], que dijo: Dijo el Mensajero de Dios ﷺ: [[k:«No es lícita la sangre de un musulmán que testifica que no hay más dios que Dios y que yo soy el Mensajero de Dios, salvo por una de tres:]] (1) la vida por la vida, (2) el casado adúltero, (3) [[k:el que se aparta de la religión, el que abandona la comunidad»]]."],
  prueba="En la colección más autorizada, apartarse de la religión figura entre las tres causas que hacen lícita la sangre de un musulmán. Es un hadiz de Ibn Masʿud, con cadena por al-Aʿmash, y la página lo marca como «acordado» entre al-Bujari y Muslim.",
  ojo="Dice que la sangre «se vuelve lícita», no «mátese» con esas palabras; y une la cláusula a «el que abandona la comunidad»: algunos lo leen como rasgo de rebelión contra la comunidad, no como mero cambio de creencia (ver AP17–AP18 y AP22). La redacción varía de una colección a otra (en Muslim es «el que abandona su religión, el que se separa de la comunidad»: AP04).", uso=USO),

 dict(id="AP04", key="M1676", tag="Hadiz · Muslim 1676 · Ibn Masʿud", specs=["AP-m1676"],
  title="Muslim 1676: «…salvo por una de tres: el casado adúltero, la vida por la vida y el que abandona su religión, el que se separa de la comunidad»",
  ref="Muslim, Sahih, Kitab al-qasama wa-l-muharibin, «Bab ma yubah bihi dam al-muslim», n.º 1676a",
  ar_ref="صحيح مسلم ١٦٧٦", site=HU, url="https://hadithunlocked.com/muslim:1676",
  es=["Nos contó Abu Bakr ibn Abi Shayba: nos contaron Hafs ibn Ghiyath, Abu Muʿawiya y Wakiʿ, de al-Aʿmash, de ʿAbd Allah ibn Murra, de Masruq, de ʿAbd Allah, que dijo: Dijo el Mensajero de Dios ﷺ: [[k:«No es lícita la sangre de un musulmán que testifica que no hay más dios que Dios y que yo soy el Mensajero de Dios, salvo por una de tres:]] el casado adúltero, la vida por la vida, [[k:y el que abandona su religión, el que se separa de la comunidad»]]."],
  prueba="La misma tradición en Muslim, con la cláusula «el que abandona su religión, el que se separa de la comunidad». Es el hadiz que la mayoría de los juristas citan junto al de Ibn Abbas (AP01) para fundar la pena.",
  ojo="Como AP03, afirma que la sangre «se hace lícita», no un procedimiento. La palabra «el que se separa de la comunidad» fue leída por unos como descripción del apóstata en general y por otros como la de quien rompe con la comunidad por la fuerza. Ambas lecturas están en los comentaristas clásicos (se verán más abajo). La captura es de la página del hadiz con cadena; el comentario de al-Nawawī no se ve en ella con claridad y se cita en otra tarjeta.", uso=USO),

 dict(id="AP07", key="B6923", tag="Compañero · Bujari 6923 · Muʿadh y Abu Musa", specs=["AP-b6923"],
  title="Bujari 6923: Muʿadh en Yemen: «No me siento hasta que sea ejecutado: es el dictamen de Dios y de Su Mensajero» (un judío que se hizo musulmán y volvió al judaísmo)",
  ref="al-Bujari, Sahih, Kitab istitabat al-murtaddin, «Bab hukm al-murtadd wa-l-murtadda», n.º 6923",
  ar_ref="صحيح البخاري ٦٩٢٣", site=HU, url="https://hadithunlocked.com/bukhari:6923",
  es=["[…] «pero ve tú, Abu Musa —o ʿAbd Allah ibn Qays—, al Yemen». Luego envió tras él a Muʿadh ibn Yabal. Cuando [Muʿadh] llegó, [Abu Musa] le echó un cojín [y dijo]: «Baja». Y había un hombre atado junto a él. Dijo [Muʿadh]: «¿Qué es esto?» Dijo [Abu Musa]: [[k:«Era judío, se hizo musulmán y luego volvió al judaísmo.»]] Dijo: «Siéntate». Dijo: [[k:«No me siento hasta que sea ejecutado: es el dictamen de Dios y de Su Mensajero»]] —tres veces—. [[k:Y mandó que lo mataran, y lo mataron.]] […]"],
  prueba="Un Compañero con comisión del Profeta (Muʿadh, enviado a Yemen) declara «dictamen de Dios y de Su Mensajero» que debe ser ejecutado el judío convertido al islam que vuelve al judaísmo, y se ejecuta. Es el relato más citado de práctica de un Compañero; la página lo marca como «acordado» (al-Bujari y Muslim).",
  ojo="Es la afirmación de Muʿadh, no una frase del Profeta; el texto no menciona si se le pidió arrepentirse (otras versiones sí: AP08). El hombre ya estaba atado cuando llegó Muʿadh; el texto no dice quién lo juzgó ni cuándo se había vuelto al judaísmo.", uso=USO),

 dict(id="AP05", key="T1458", tag="Hadiz · Tirmidhi 1458 · ʿAli e Ibn Abbas", specs=["AP-tr1458"],
  title="Tirmidhi 1458: ʿAli quema a unos apóstatas; Ibn Abbas: «los habría matado… quien cambie su religión, matadlo»; ʿAli: «Ibn Abbas ha dicho la verdad»; y «la práctica entre la gente del conocimiento es esta»",
  ref="al-Tirmidhi, Sunan, Abwab al-hudud, «Bab ma ya'a fi l-murtadd», n.º 1458",
  ar_ref="سنن الترمذي ١٤٥٨", site=HU, url="https://hadithunlocked.com/tirmidhi:1458",
  es=["[…] que ʿAli quemó a unos [hombres] que habían apostatado del islam. Eso llegó a Ibn Abbas y dijo: [[k:«Si hubiera sido yo, los habría matado, por el dicho del Mensajero de Dios ﷺ: ‹Quien cambie su religión, matadlo›]], y no los habría quemado, por el dicho del Mensajero de Dios ﷺ: ‹No castiguéis con el castigo de Dios›». Eso llegó a ʿAli y dijo: [[k:«Ibn Abbas ha dicho la verdad.»]] Dijo Abu ʿIsa [al-Tirmidhi]: este hadiz es ṣaḥīḥ ḥasan, [[k:y la práctica según esto entre la gente del conocimiento, en cuanto al apóstata;]] [[a:y discreparon sobre la mujer cuando apostata del islam: un grupo de la gente del conocimiento dijo: se la mata —es el dicho de al-Awzaʿi, Ahmad e Ishaq—; y un grupo de ellos dijo: se la encarcela y no se la mata —es el dicho de Sufyan al-Thawri y otros de la gente de Kufa—]]."],
  prueba="Al-Tirmidhi (m. 279 H) recoge la misma historia con la variante «habían apostatado del islam» y con la aceptación de ʿAli («Ibn Abbas ha dicho la verdad»), y añade un testimonio de época: «la práctica entre la gente del conocimiento es esta, sobre el apóstata».",
  ojo="Es el mismo hadiz de Ibn Abbas/ʿIkrima de AP01–AP02, no uno distinto. Las frases «Ibn Abbas ha dicho la verdad» no están en las versiones de al-Bujari de esas tarjetas; según el comentario de Ibn Hajar que se ve en la página del hadiz (no capturado), otras versiones dicen que ʿAli exclamó «¡pobre Ibn Abbas!»: la reacción de ʿAli varía entre versiones. Y el propio al-Tirmidhi anota que sobre la mujer hay desacuerdo: la pena no era uniforme.", uso=USO),

 dict(id="AP06", key="AD4502", tag="Hadiz · Abu Dawud 4502 · ʿUthman", specs=["AP-ad4502"],
  title="Abu Dawud 4502: ʿUthman, sitiado: «No es lícita la sangre de un musulmán salvo por una de tres: incredulidad tras el islam, adulterio tras estar casado, o matar a una persona»",
  ref="Abu Dawud, Sunan, Kitab al-diyat, n.º 4502 (hadiz de ʿUthman, citado también por al-Shafiʿi: AP12)",
  ar_ref="سنن أبي داود ٤٥٠٢", site=HU, url="https://hadithunlocked.com/abudawud:4502",
  es=["[…] «Estábamos con ʿUthman mientras estaba sitiado en la casa […] Salió hacia nosotros con el color cambiado y dijo: ‹Me están amenazando de muerte›. Dijimos: ‹Dios te basta contra ellos, Comendador de los creyentes›. Dijo: ‹¿Y por qué habrían de matarme? Oí al Mensajero de Dios ﷺ decir: [[k:No es lícita la sangre de un musulmán salvo por una de tres: incredulidad tras el islam, o adulterio tras estar casado, o matar a una persona sin que sea [en pago de otra] persona.›]] Por Dios, [[a:no cometí adulterio ni en la época preislámica ni en el islam, y no quise cambiar mi religión por otra desde que Dios me guió, ni maté a nadie.]] ¿Por qué, pues, me matan?›»"],
  prueba="Otra versión de las tres causas, con la fórmula «incredulidad tras el islam» (kufr baʿda islam), puesta en boca del califa ʿUthman durante su asedio: el hadiz como prueba de que sus sitiadores no tenían ninguna de las tres causas contra él.",
  ojo="Como en AP03–AP04, dice que la sangre «se hace lícita»; no fija procedimiento ni pide arrepentimiento previo. La página lo muestra con calificaciones de eruditos modernos que no he evaluado. Aquí es un dicho usado en defensa propia, no un caso de ejecución.", uso=USO),

 dict(id="AP08", key="M20", tag="Compañeros · Abu Dawud 4356 e Ibn Abi Shayba 30930 · Muʿadh", specs=["AP-ad4356", "AP-ias3"],
  title="El mismo caso de Yemen con plazo de arrepentimiento: Abu Dawud 4356: «veinte noches», luego Muʿadh lo decapita; Ibn Abi Shayba 30930: «dos meses»",
  ref="Abu Dawud, Sunan, Kitab al-hudud, «Bab al-hukm fi-man irtadda», n.º 4356; e Ibn Abi Shayba, al-Musannaf (ed. al-Shathri), vol. 16 p. 45, n.º 30930",
  ar_ref="سنن أبي داود ٤٣٥٦ · مصنف ابن أبي شيبة ٣٠٩٣٠", site=HU + " · " + SH, url="https://hadithunlocked.com/abudawud:4356 · https://shamela.ws/book/333/35488",
  es=["[…] Nos contó Muhammad ibn al-ʿAlaʾ: nos contó Hafs: nos contó al-Shaybani, de Abu Burda, con esta historia, [dijo]: «Trajeron a Abu Musa un hombre que había apostatado del islam, [[k:y lo llamó [al islam] veinte noches, o cerca de eso;]] [[k:luego vino Muʿadh y lo llamó, y se negó, y le cortaron la cabeza.]]» Dijo Abu Dawud: [[a:y lo transmitió ʿAbd al-Malik ibn ʿUmayr, de Abu Burda, sin mencionar la petición de arrepentimiento]]; […]",
      "30930 - Nos contó Abu Bakr, dijo: nos contó ʿAbbad ibn al-ʿAwwam, de Saʿid, de Qatada, de Humayd ibn Hilal: [[k:que Muʿadh ibn Yabal fue a ver a Abu Musa, y junto a él había un hombre judío. Dijo: ‹¿Qué es esto?› Dijo: ‹Este judío se hizo musulmán y luego apostató, y]] [[k:Abu Musa lo ha hecho arrepentirse [durante] dos meses›. Dijo: Entonces dijo Muʿadh: ‹No me siento hasta que le corte el cuello›]], [dictamen] de Dios y [dictamen] de Su Mensajero.",
      "[[a:(Nota del editor:) Débil y cortado: Humayd ibn Hilal no oyó de Muʿadh ni de Abu Musa, y Saʿid [ibn Abi ʿAruba] se confundió [al envejecer].]]"],
  prueba="Dos relatos tempranos del mismo caso (un judío que se hizo musulmán y volvió al judaísmo, en Yemen): en Abu Dawud 4356 Abu Musa lo llama «veinte noches, o cerca de eso» y luego Muʿadh lo hace decapitar; en Ibn Abi Shayba 30930 son «dos meses». En ambos la ejecución llega tras un plazo de arrepentimiento.",
  ojo="En Bujari 6923 (AP07) no hay plazo: «mandó que lo mataran». El propio Abu Dawud anota que otros transmisores no mencionan la petición de arrepentimiento (azul). La página de Abu Dawud califica la cadena «su isnad es ṣaḥīḥ» (al-Albani); el editor de Ibn Abi Shayba la suya de «débil y cortada». Las duraciones difieren entre sí (veinte noches / dos meses), lo que indica transmisión por el sentido.", uso=USO),

 dict(id="AP09", key="IAS1", tag="Compañeros · Ibn Abi Shayba 30925 y 30926 · ʿUmar y ʿAli", specs=["AP-ias1", "AP-ias2"],
  title="Ibn Abi Shayba: ʿUmar: «¿no lo metisteis en una casa, con un pan al día, y lo hicisteis arrepentirse tres [veces]?»; ʿAli: «se hace arrepentir al apóstata tres veces; si vuelve, se le mata»",
  ref="Ibn Abi Shayba, al-Musannaf (ed. al-Shathri), «Fi l-murtadd ʿan al-islam ma ʿalayhi», vol. 16 p. 44, n.º 30925 y 30926",
  ar_ref="مصنف ابن أبي شيبة ٣٠٩٢٥، ٣٠٩٢٦", site=SH, url="https://shamela.ws/book/333/35483 · https://shamela.ws/book/333/35484",
  es=["30925 - Nos contó Abu Bakr, dijo: nos contó Ibn ʿUyayna, de Muhammad ibn ʿAbd al-Rahman, de su padre, que dijo: Cuando llegó a ʿUmar [la noticia de] la conquista de Tustar —y Tustar es de tierras de Basora— les preguntó: «¿Hay alguna noticia de lejos?» Dijeron: «Un hombre de los musulmanes se unió a los politeístas y lo capturamos». Dijo: «¿Qué hicisteis con él?» Dijeron: «Lo matamos». Dijo: [[k:«¿No lo metisteis en una casa, le cerrasteis una puerta, le disteis cada día un pan, y luego le [pedisteis que se] arrepintiera tres [veces]? Si se arrepentía [bien], y si no, lo matabais.»]] Luego dijo: [[k:«¡Oh Dios! No estuve presente, no [lo] ordené, y no [lo] aprobé cuando me llegó.»]]",
      "[[a:(Nota del editor:) Débil: Muhammad es Ibn Abi Layla, de mala memoria.]]",
      "30926 - Nos contó Abu Bakr, dijo: nos contó Hafs ibn Ghiyath, de Ashʿath, de al-Shaʿbi, que dijo: Dijo ʿAli: [[k:«Se hace arrepentir al apóstata tres veces; si vuelve [a apostatar], se le mata.»]]",
      "[[a:(Nota del editor:) Débil, por la debilidad de Ashʿath.]]"],
  prueba="En la colección de Ibn Abi Shayba (m. 235 H) la práctica temprana atribuida a ʿUmar y a ʿAli es pedir el arrepentimiento (tres veces o tres días, con un pan diario) y matar a quien no se arrepiente. ʿUmar, al saber que lo habían matado sin ese trámite, dice que no estuvo presente, no lo ordenó ni lo aprobó.",
  ojo="El editor califica de débiles las dos cadenas (la de ʿUmar por Ibn Abi Layla, de memoria mala; la de ʿAli por Ashʿath). Son testimonio de lo que se transmitía, no de lo que está probado. Y el relato de ʿUmar apunta más a un reproche por matar sin plazo que a una orden de matar. Es el relato en que se apoyan las escuelas que exigen la petición de arrepentimiento. El mismo episodio de ʿUmar, con otras cadenas y detalles, está leído ahora en el Muwatta' (AP34), ʿAbd al-Razzaq 18773 (AP24) y Saʿid ibn Mansur 2586 (AP31).", uso=USO),

 dict(id="AP10", key="IAS2", tag="Compañeros · Ibn Abi Shayba 34960 y 34937 · ʿAli y ʿUmar", specs=["AP-ias4", "AP-ias5"],
  title="Ibn Abi Shayba: ʿAli ofrece el islam a Mustawrid al-ʿIjli (apóstata) y, al negarse, lo mata; ʿUmar a ʿAmr ibn al-ʿAs: «pídele que se arrepienta… y si no, córtale el cuello»",
  ref="Ibn Abi Shayba, al-Musannaf (ed. al-Shathri), vol. 18 pp. 266 y 261, n.º 34960 y 34937",
  ar_ref="مصنف ابن أبي شيبة ٣٤٩٦٠، ٣٤٩٣٧", site=SH, url="https://shamela.ws/book/333/40131 · https://shamela.ws/book/333/40105",
  es=["34960 - Nos contó Abu Muʿawiya, de al-Aʿmash, de Abu ʿAmr al-Shaybani, de ʿAli: [[k:que le trajeron a Mustawrid al-ʿIjli, que había apostatado; le ofreció el islam y se negó; entonces lo mató y puso su herencia entre sus herederos musulmanes.]] [[a:(Editor:) Ṣaḥīḥ.]]",
      "34937 - Nos contó ʿAbd al-Rahim ibn Sulayman, de Hayyay, de ʿAmr ibn Shuʿayb, de su padre, de su abuelo, que dijo: ʿAmr ibn al-ʿAs escribió a ʿUmar ibn al-Jattab [[k:que un hombre cambia la fe por la incredulidad después de haber creído]]; y ʿUmar le escribió: [[k:«Pídele que se arrepienta; si se arrepiente, acéptaselo; y si no, córtale el cuello.»]]",
      "[[a:(Nota del editor:) Cortado en la práctica; Hayyay es mudallis [encubre eslabones].]]"],
  prueba="Dos relatos más: ʿAli ofrece el islam a un apóstata y, ante la negativa, lo mata (el editor lo califica ṣaḥīḥ); y ʿUmar ordena a su gobernador de Egipto: pedirle el arrepentimiento, aceptarlo si lo hace y, si no, cortarle el cuello (cadena «cortada» según el editor).",
  ojo="De nuevo el orden es: primero el arrepentimiento, luego la ejecución. Son casos de quien declara su cambio, no de creencias privadas. Mustawrid aparece también en ʿAbd al-Razzaq 18788 y 18789 (AP26), que leí yo; según mis agentes, no figura en Ṭabarī ni en al-Baladhuri (no lo comprobé). Nada se dice aquí de mujeres.", uso=USO),

 dict(id="AP11", key="AD4359", tag="Sīra · Abu Dawud 4359 y 2762 · Ibn Abi Sarh e Ibn al-Nawwaha", specs=["AP-ad4359", "AP-ad2762"],
  title="Abu Dawud 4359: Ibn Abi Sarh en La Meca: el Profeta se niega tres veces y luego acepta su lealtad: «¿no había un hombre sensato que lo matara?»; y 2762: Ibn Masʿud ejecuta a Ibn al-Nawwaha",
  ref="Abu Dawud, Sunan, Kitab al-hudud n.º 4359 y Kitab al-yihad n.º 2762",
  ar_ref="سنن أبي داود ٤٣٥٩، ٢٧٦٢", site=HU, url="https://hadithunlocked.com/abudawud:4359 · https://hadithunlocked.com/abudawud:2762",
  es=["[…] «Cuando fue el día de la conquista de La Meca, ʿAbd Allah ibn Saʿd ibn Abi Sarh se escondió junto a ʿUthman ibn ʿAffan; [ʿUthman] lo trajo y lo presentó ante el Profeta ﷺ y dijo: ‹¡Mensajero de Dios! Acepta la lealtad de ʿAbd Allah›. [El Profeta] levantó la cabeza y lo miró tres veces, [[a:y cada vez se negaba;]] [[k:luego aceptó su lealtad después de tres.]] Luego se volvió a sus compañeros y dijo: [[k:‹¿No había entre vosotros un hombre sensato que se levantara hacia éste, cuando me vio retirar mi mano de su lealtad, y lo matara?›]] Dijeron: ‹No sabemos qué había en tu interior, Mensajero de Dios; ¿por qué no nos hiciste una seña con el ojo?› Dijo: [[k:‹No conviene a un profeta tener traición de ojos.›]]»",
      "[…] que [Haritha ibn Mudarrib] fue a ver a ʿAbd Allah [ibn Masʿud] y dijo: «No hay entre yo y ningún árabe rencor, pero pasé por una mezquita de los Banu Hanifa y he aquí que creen en Musaylima». ʿAbd Allah envió por ellos, los trajeron, [[k:y les pidió que se arrepintieran, excepto a Ibn al-Nawwaha, a quien dijo: ‹Oí al Mensajero de Dios ﷺ decir: ‹Si no fueras un mensajero, te cortaría el cuello›; hoy no eres mensajero›;]] [[k:y mandó a Qaraza ibn Kaʿb, que le cortó el cuello en el mercado.]] Luego dijo: «Quien quiera ver a Ibn al-Nawwaha muerto en el mercado, [que vaya]»."],
  prueba="Dos casos tempranos: el Profeta, en La Meca, lamenta que nadie matara a ʿAbd Allah ibn Saʿd ibn Abi Sarh antes de aceptarle la lealtad (la página califica el hadiz «ṣaḥīḥ», al-Albani); e Ibn Masʿud, en Kufa, hace arrepentirse a los seguidores de Musaylima y ejecuta a Ibn al-Nawwaha.",
  ojo="En 4359 el Profeta NO mata a Ibn Abi Sarh: acepta su lealtad. El texto de 4359 no dice que Ibn Abi Sarh hubiera apostatado ni da el motivo por el que habría debido matarse: esa lectura la añaden otros (Ibn Taymiyya, AP17; según mi agente, Ibn Ishaq, que no he leído). En 2762, Ibn al-Nawwaha había sido enviado de Musaylima: Ibn Masʿud recuerda la frase del Profeta a los enviados («si no fueras un mensajero…», Abu Dawud 2761): el caso mezcla apostasía, adhesión a un falso profeta y fin de la inmunidad de enviado; no es un caso de creencia privada.", uso=USO),

 dict(id="AP12", key="UMM", tag="204 H · al-Shafiʿi, al-Umm", specs=["AP-umm"],
  title="al-Shafiʿi: «incredulidad tras la fe» hace lícita la sangre; «no discreparon los musulmanes en que no es lícito rescatar al apóstata, ni perdonarle, ni dejarlo… hasta que se haga musulmán o sea muerto»",
  ref="al-Shafiʿi, Kitab al-Umm, Kitab al-hudud, «Bab al-murtadd al-kabir»",
  ar_ref="كتاب الأم، كتاب الحدود، باب المرتد الكبير", site="ar.wikisource.org (transcripción del texto; sin paginación de edición impresa)", url="https://ar.wikisource.org/wiki/كتاب_الأم/كتاب_الحدود/باب_المرتد_الكبير",
  es=["[…] Nos informó el digno de confianza, de Hammad ibn Zayd, de Yahya ibn Saʿid, de Abu Umama ibn Sahl, de ʿUthman ibn ʿAffan, que el Mensajero de Dios ﷺ dijo: [[k:«No es lícita la sangre de un musulmán salvo por una de tres: incredulidad tras la fe, adulterio tras estar casado, y matar a una persona sin que sea [en pago de otra] persona.»]] [Dijo al-Shafiʿi:] No cabe, en el dicho del Profeta ﷺ «No es lícita la sangre de un musulmán salvo por una de tres», [siendo] una de ellas la incredulidad tras la fe, sino que la palabra de incredulidad haga lícita la sangre como la hace lícita el adulterio tras estar casado, o que la palabra de incredulidad haga lícita la sangre [[a:salvo que su autor se arrepienta]]; y el Libro de Dios, y luego la sunna de Su Mensajero, indican que el sentido del dicho del Mensajero «incredulidad tras la fe» es [[a:cuando no se arrepiente de la incredulidad]]. […] El apóstata es más grave en juicio que quien nunca dejó de ser politeísta […]. Y [[k:no discreparon los musulmanes en que no es lícito rescatar a un apóstata tras su fe, ni concederle gracia, ni tomarle rescate,]] [[k:ni dejarlo en ningún caso hasta que se haga musulmán o sea muerto.]] Y Dios sabe más."],
  prueba="Al-Shafiʿi (m. 204 H), el fundador de una de las cuatro escuelas, escribe en al-Umm que «incredulidad tras la fe» (hadiz de ʿUthman, AP06) hace lícita la sangre y que el apóstata no puede ser rescatado, perdonado ni dejado «hasta que se haga musulmán o sea muerto»; y añade «no discreparon los musulmanes» en ello.",
  ojo="Su «no discreparon los musulmanes» se refiere a no rescatar ni perdonar al apóstata (frases en naranja), no a que nadie discrepara de la pena. Y condiciona la lectura del hadiz: «salvo que su autor se arrepienta» (azul), es decir, entiende «incredulidad tras la fe» como la que no se retracta. Es transcripción de Wikisource, sin edición impresa identificada; el texto de al-Umm tiene además un capítulo propio de «desacuerdo con algunos» sobre este tema (no capturado).", uso=USO),

 dict(id="AP13", key="IST1", tag="463 H · Ibn ʿAbd al-Barr sobre Malik, al-Istidhkar", specs=["AP-ist151"],
  title="Ibn ʿAbd al-Barr: el hadiz de Malik «quien cambie su religión, cortadle el cuello» es mursal; «lo correcto» es el de Ibn Abbas; los Compañeros pedían el arrepentimiento; Malik: zanadiqa sin plazo",
  ref="Ibn ʿAbd al-Barr, al-Istidhkar, vol. 7 p. 151, «Bab al-qada' fi-man irtadda ʿan al-islam» (sobre el Muwatta' de Malik, n.º 1407 de esta edición)",
  ar_ref="الاستذكار ج٧ ص١٥١", site=SH, url="https://shamela.ws/book/1722/3117",
  es=["(18 - Capítulo: el dictamen sobre quien apostata del islam) 1407 - Malik, de Zayd ibn Aslam, que el Mensajero de Dios ﷺ dijo: [[k:«Quien cambie su religión, cortadle el cuello.»]] [[a:Así transmitieron este hadiz el conjunto de los transmisores del Muwatta', de Malik, como mursal [sin Compañero];]] y se transmitió de Malik, por esto, una cadena rechazable, por Nafiʿ, de Ibn ʿUmar, [[a:que no es válida;]] [[k:y lo correcto sobre esto es el hadiz de Ibn Abbas]] […] «Quien cambie su religión, matadlo». Y el sentido aparente de este hadiz obliga, en cualquier caso, a que quien cambie la religión del islam o la sustituya sea muerto y se le corte el cuello, [[k:salvo que los Compañeros dijeron que se le pide el arrepentimiento: si se arrepiente, [bien], y si no, se le mata;]] [[a:como si el hadiz, para ellos, hubiera salido sobre quien cambió su religión y persistió en ello.]] Dijo Malik: «El sentido del dicho del Profeta ﷺ ‹quien cambie su religión, cortadle el cuello› es, a nuestro parecer y Dios sabe más, [de] quien sale del islam a otra cosa, [[k:como los zanadiqa y semejantes: ésos, cuando se les descubre, se les mata y no se les pide arrepentimiento,]] porque no se conoce su arrepentimiento y porque ocultaban la incredulidad y manifestaban el islam […] Y en cuanto a quien salió del islam a otra cosa y lo manifestó, [[k:ése se le pide arrepentimiento: si se arrepiente, [bien], y si no, se le mata.]]"],
  prueba="Ibn ʿAbd al-Barr (m. 463 H), el gran comentarista del Muwatta' de Malik (m. 179 H), muestra que en el círculo de Malik el hadiz «quien cambie su religión, cortadle el cuello» se leía como pena de muerte: a los zanadiqa (apóstatas que ocultan su incredulidad) sin plazo; al apóstata declarado, tras pedirle el arrepentimiento. Y dice que lo «correcto» es el hadiz de Ibn Abbas (AP01).",
  ojo="El mismo comentarista advierte de límites: la versión de Malik es mursal (sin Compañero) y otra cadena de Malik por Nafiʿ e Ibn ʿUmar es «rechazable, no válida»; y para los Compañeros, el hadiz «salió sobre quien cambió su religión y persistió», es decir, la pena exige persistencia. La siguiente tarjeta aclara el alcance (no se aplica al dhimmi que cambia entre religiones). Aquí dice «Ibn Abbas» y «bin Abbas» al estilo de la edición (sin alif); texto de Shamela, no de la edición impresa. El texto del Muwatta' mismo (36-25) lo he leído después directamente (AP33) y coincide.", uso=USO),

 dict(id="AP14", key="IST2", tag="463 H · Ibn ʿAbd al-Barr, al-Istidhkar (alcance)", specs=["AP-ist152"],
  title="Ibn ʿAbd al-Barr: la pena es para quien sale del islam; «el conjunto de los sabios»: quien pasa del judaísmo al cristianismo, siendo dhimmi, no es muerto; «no hay desacuerdo entre los sabios en lo descrito»",
  ref="Ibn ʿAbd al-Barr, al-Istidhkar, vol. 7 p. 152, mismo capítulo",
  ar_ref="الاستذكار ج٧ ص١٥٢", site=SH, url="https://shamela.ws/book/1722/3118",
  es=["[…] Si unos hombres estuvieran en ello, yo vería que se les llame al islam y se les pida el arrepentimiento: si se arrepienten, se les acepta; y [[k:si no se arrepienten, se les mata.]] Y no se refirió con ello, a nuestro parecer y Dios sabe más, a quien sale del judaísmo al cristianismo, ni del cristianismo al judaísmo, ni a quien cambia su religión de entre todas las religiones salvo el islam; [[k:así que quien sale del islam a otra cosa y lo manifiesta, ése es a quien se refirió.]] Dijo Abu ʿUmar [Ibn ʿAbd al-Barr]: En esto [está] el conjunto de los sabios sobre quien sale de la religión del judaísmo al cristianismo, o del cristianismo al judaísmo o al zoroastrismo: [[a:que no se le mata si es dhimmi y conserva su dhimma,]] porque el cristianismo, el judaísmo y el zoroastrismo son religiones de las que el Corán y la sunna han dispuesto que sus adeptos se dejen como dhimmies si pagan la yizya y se la dan a los musulmanes: [[a:no hay desacuerdo entre los sabios en lo que hemos descrito]]."],
  prueba="El mismo pasaje delimita a quién se aplica «quien cambie su religión»: según Malik y «el conjunto de los sabios» (Ibn ʿAbd al-Barr), a quien sale del islam y lo manifiesta; no a un dhimmi que pasa del judaísmo al cristianismo (o a otra de esas religiones).",
  ojo="Esa excepción la presenta como acuerdo entre los sabios, pero en la misma página (no capturado) cuenta que al-Shafiʿi, según al-Muzani, decía que el imán puede expulsarlo a tierra de guerra, y que otra versión (Ibn ʿAbd al-Hakam) admite matarlo «por el sentido aparente del hadiz». No elimina la pena de quien abandona el islam; solo acota a quién se refiere.", uso=USO),

 dict(id="AP15", key="MAB98", tag="c. 483 H · al-Sarakhsi, al-Mabsut (regla)", specs=["AP-mab98"],
  title="al-Sarakhsi: «si un musulmán apostata se le ofrece el islam; si se hace musulmán [bien], y si no, se le mata en el acto» (salvo que pida plazo: tres días); fundamento: Corán 48:16 y «quien cambie su religión, matadlo»",
  ref="al-Sarakhsi, al-Mabsut, Kitab al-siyar, «Bab al-murtaddin», vol. 10 p. 98",
  ar_ref="المبسوط للسرخسي ج١٠ ص٩٨", site=SH, url="https://shamela.ws/book/5423/2103",
  es=["(Capítulo de los apóstatas) Dijo —Dios esté complacido con él—: Si un musulmán apostata, [[k:se le ofrece el islam; si se hace musulmán [bien], y si no, se le mata en el acto,]] [[a:salvo que pida que se le dé un plazo; si lo pide, se le da un plazo de tres días.]] Y [[k:el fundamento de la obligación de matar a los apóstatas]] es Su dicho, Altísimo, {o se harán musulmanes} [48:16] —se dijo: el versículo trata de los apóstatas—, y dijo ﷺ: [[k:«Quien cambie su religión, matadlo»]]; y [[k:se ha transmitido que se mató al apóstata por su apostasía, de ʿAli, Ibn Masʿud, Muʿadh y otros Compañeros.]]"],
  prueba="Al-Sarakhsi (m. c. 483 H), gran jurista hanafí, formula en al-Mabsut la regla clásica: al apóstata se le ofrece el islam y, si no acepta, se le mata en el acto (salvo que pida plazo: tres días). Como fundamento cita Corán 48:16 («o se harán musulmanes»), el hadiz «quien cambie su religión, matadlo» y la práctica de ʿAli, Ibn Masʿud y Muʿadh.",
  ojo="Es formulación de escuela, siglos después de los hechos. Sobre 48:16 dice «se dijo: el versículo trata de los apóstatas» (no es el texto coránico explícito; véanse Ṭabarī y Qurṭubi más abajo: ningún versículo fija pena mundana por sí solo). Atribuye a los Compañeros una práctica sin dar cadena en esta página. Y la siguiente tarjeta muestra cómo el mismo al-Sarakhsi explica por qué se mata (no «por la incredulidad»).", uso=USO),

 dict(id="AP16", key="MAB110", tag="c. 483 H · al-Sarakhsi, al-Mabsut (por qué se mata)", specs=["AP-mab110"],
  title="al-Sarakhsi: «matar no es retribución por la apostasía, sino que es debido por la persistencia en la incredulidad… se le mata para repeler el combate»; por eso las mujeres no se matan",
  ref="al-Sarakhsi, al-Mabsut, Kitab al-siyar, «Jana l-murtadd jinaya», vol. 10 p. 110",
  ar_ref="المبسوط للسرخسي ج١٠ ص١١٠", site=SH, url="https://shamela.ws/book/5423/2115",
  es=["[…] según su sentido aparente; la sustitución se da también en el infiel que se hace musulmán: sabemos entonces que [el hadiz] es general y que le alcanza una excepción, [[k:así que lo particularizamos y lo aplicamos a los hombres,]] por la prueba que hemos dicho. Y la apóstata que fue muerta era combatiente: [[k:Umm Marwan combatía e incitaba al combate y era obedecida entre ellos]], y Umm Furqa tenía treinta hijos y los incitaba a combatir a los musulmanes, y en su muerte había quebrantar su poder; y cabe que eso viniera de al-Siddiq [Abu Bakr] [[a:por vía de conveniencia y de política]] […]",
      "[…] Y esto porque [[k:matar no es retribución por la apostasía, sino que es debido por la persistencia en la incredulidad.]] ¿No ves que si se hace musulmán, [la pena] cae por desaparecer la persistencia?, y lo que es debido como retribución no cae con el arrepentimiento, como las penas fijas (hudud) […] Lo corrobora que cambiar de religión y la incredulidad de origen son de las mayores ofensas, pero son entre el siervo y su Señor, [[a:y la retribución por ellas se difiere a la morada de la retribución;]] y lo que se adelanta en este mundo son medidas de gobierno legisladas por intereses que vuelven a los siervos, como el talión para proteger las vidas, la pena del adulterio para proteger los linajes y los lechos, la del robo para proteger los bienes, la de la calumnia para proteger el honor, la del vino para proteger la razón; [[k:y por la persistencia en la incredulidad se es combatiente contra los musulmanes, y se le mata para repeler el combate]] […]"],
  prueba="El mismo jurista explica la lógica hanafí: la muerte del apóstata «no es retribución por la apostasía» —esa se difiere al más allá— sino que se debe «por la persistencia en la incredulidad», que lo convierte en combatiente contra los musulmanes, y se le mata «para repeler el combate». Por eso a la mujer, que no es apta para combatir, se la encarcela y no se la mata; y los casos en que se mató a mujeres (Umm Marwan, Umm Furqa) los explica por combatir o por política.",
  ojo="Es un razonamiento hanafí posterior; no dice que el apóstata pacífico quede sin pena: sigue siendo muerto «por la persistencia», sin que haga falta una acción armada concreta. Su efecto es separar la ejecución del castigo religioso: la retribución de la incredulidad es del más allá. Quien cite a al-Sarakhsi tiene que citar a la vez AP15 (la regla) y esta tarjeta (su porqué). Texto de Shamela.", uso=USO),

 dict(id="AP17", key="SAR1", tag="728 H · Ibn Taymiyya, al-Sarim al-maslul (arrepentimiento y La Meca)", specs=["AP-sar324", "AP-sar325"],
  title="Ibn Taymiyya: la mayoría pide el arrepentimiento; ʿUbayd ibn ʿUmayr y Tawus: se mata sin pedirlo (lo que él defiende); y argumenta desde Ibn Abi Sarh, Miqyas e Ibn Jatal, «que eran apóstatas»",
  ref="Ibn Taymiyya, al-Sarim al-maslul ʿala shatim al-rasul, «al-Masʾala al-thalitha: annahu yuqtal wa-la yustatab…», pp. 321–322 impresas",
  ar_ref="الصارم المسلول ص٣٢١-٣٢٢", site=SH, url="https://shamela.ws/book/7344/324 · https://shamela.ws/book/7344/325",
  es=["Sección. Establecido eso, [[k:lo que sostiene la mayoría de la gente del conocimiento es que al apóstata se le pide el arrepentimiento;]] [[a:y la doctrina de Malik y de Ahmad es que se le pide el arrepentimiento y se le da un plazo de tres días tras ello]], y si eso es obligatorio o recomendado hay dos narraciones de ellos; […] Y dijo al-Thawri: [[a:«se le da plazo mientras se espere su arrepentimiento»]]… Y ʿUbayd ibn ʿUmayr y Tawus fueron a que [[k:se le mata y no se le pide el arrepentimiento,]] porque [el Profeta] mandó matar «al que cambia su religión» y «al que deja su religión, el que se separa de la comunidad» y no mandó pedirle el arrepentimiento […]",
      "[…] Y lo indica también que el Profeta ﷺ [[k:declaró lícita, el día de la conquista de La Meca, la sangre de ʿAbd Allah ibn Saʿd ibn Abi Sarh, de Miqyas ibn Hubaba y de ʿAbd Allah ibn Jatal, y eran apóstatas]], y no les pidió el arrepentimiento, sino que fueron muertos esos dos hombres, y [[a:el Profeta ﷺ se abstuvo de aceptar la lealtad de Ibn Abi Sarh, por si algún musulmán lo mataba;]] [[k:con lo cual se supo que matar al apóstata es lícito mientras no se haga musulmán, y que no se le pide el arrepentimiento.]]"],
  prueba="Ibn Taymiyya (m. 728 H) resume las posturas sobre la petición de arrepentimiento (mayoría: se pide; Malik y Ahmad: tres días; ʿUbayd ibn ʿUmayr y Tawus: se mata sin pedirlo) y defiende la última en ese capítulo. Su argumento es la conducta del Profeta el día de la conquista de La Meca: declaró lícita la sangre de tres «apóstatas» sin pedirles el arrepentimiento. Muestra cómo se leían en el siglo VIII H los casos tempranos (AP11).",
  ojo="Está en un capítulo sobre quien insulta al Profeta («se mata y no se le pide arrepentimiento, sea musulmán o infiel»): su argumento sirve a esa tesis. La propia página presenta la suya como minoritaria («lo que sostiene la mayoría: se pide el arrepentimiento»). Y su lectura de Ibn Abi Sarh choca con Abu Dawud 4359 (AP11): el Profeta acepta su lealtad; Ibn Taymiyya lo registra («se abstuvo de aceptar su lealtad…») y llama «apóstatas» a los tres, cosa que depende de narraciones como las de Ibn Ishaq.", uso=USO),

 dict(id="AP18", key="SAR2", tag="728 H · Ibn Taymiyya, al-Sarim al-maslul (lectura restrictiva)", specs=["AP-sar322"],
  title="Ibn Taymiyya: «quien cambia su religión» solo si persiste; y «el que deja su religión, el que se separa de la comunidad» puede explicarse por el combatiente (Abu Dawud, de ʿAʾisha), o por quien apostató y combatió",
  ref="Ibn Taymiyya, al-Sarim al-maslul, mismo capítulo, p. 319 impresa",
  ar_ref="الصارم المسلول ص٣١٩", site=SH, url="https://shamela.ws/book/7344/322",
  es=["[…] Y en cuanto a su dicho ﷺ «Quien cambie su religión, matadlo», [[k:decimos [que lo aceptamos]: solo es ‹quien cambia› si persiste en ello y continúa en eso; pero si vuelve a la religión verdadera, no es quien cambia;]] y asimismo, si vuelve a los musulmanes, no es ‹el que deja su religión, el que se separa de la comunidad›, sino que se aferra a su religión y está unido a la comunidad. […] Aparte de que [[a:su dicho «el que deja su religión, el que se separa de la comunidad» puede explicarse por el combatiente, el salteador de caminos,]] tal como lo transmitió Abu Dawud en su Sunan, explicado, de ʿAʾisha: «[no es lícita la sangre…] salvo por una de tres: un hombre que cometió adulterio tras estar casado, y se le lapida; un hombre que salió combatiendo a Dios y a Su Mensajero, y se le mata o se le crucifica o se le destierra; o que mató a una persona, y se le mata por ella» […] [[a:o que lo que se quiere decir es quien apostató y combatió, como los ʿUraniyyin y Miqyas ibn Hubaba, que apostató, mató y tomó el dinero]]…"],
  prueba="Ibn Taymiyya ofrece, en el mismo libro, una lectura restrictiva del hadiz de las tres causas (AP03–AP04): la cláusula «el que deja su religión, el que se separa de la comunidad» puede entenderse, como en la versión de Abu Dawud por ʿAʾisha («un hombre que salió combatiendo a Dios y a Su Mensajero»), como el apóstata combatiente; y quien «cambia su religión» solo lo es mientras persiste.",
  ojo="Es un argumento secundario (dice «puede explicarse»), dado frente a una objeción, en un capítulo sobre quien insulta al Profeta. Ibn Taymiyya no concluye que el apóstata pacífico no se mate: en AP17 sostiene lo contrario para quien insulta, y sobre los demás recoge la regla común. Esta tarjeta muestra que la propia tradición clásica conoce la lectura «solo el apóstata que combate», no que la adopte como regla.", uso=USO),

 dict(id="AP19", key="QR217", tag="671 H · al-Qurtubi sobre 2:217", specs=["AP-qr217"],
  title="al-Qurtubi, sobre 2:217: los sabios discreparon: arrepentimiento (de una hora a cien veces), muerte sin arrepentimiento, zanadiqa, mujeres; el hadiz de las tres causas «abarca a todo el que cometa incredulidad tras su fe, y es lo más válido»",
  ref="al-Qurtubi, al-Yamiʿ li-ahkam al-Qurʾan, sobre el Corán 2:217, cuestión novena",
  ar_ref="تفسير القرطبي، البقرة ٢١٧", site=KSU, url="https://quran.ksu.edu.sa/tafseer/qortobi/sura2-aya217.html",
  es=["Novena: los sabios discreparon sobre el apóstata: ¿se le pide el arrepentimiento o no? […] Dijo un grupo: [[k:se le pide el arrepentimiento; si se arrepiente, [bien], y si no, se le mata;]] y algunos dijeron: [[a:una hora]]. Otros: [[a:un mes]]. Otros: tres [días/veces], según lo que se transmite de ʿUmar y ʿUthman, y es el dicho de Malik. Dijo al-Hasan: [[a:cien veces]]; y se transmitió de él que se le mata sin arrepentimiento, y así lo dijo al-Shafiʿi en uno de sus dos dichos, y es uno de los dos dichos de Tawus y de ʿUbayd ibn ʿUmayr. Y Sahnun mencionó que ʿAbd al-ʿAziz ibn Abi Salama al-Mayishun decía: [[k:«se mata al apóstata y no se le pide el arrepentimiento»,]] y argumentó con el hadiz de Muʿadh y Abu Musa, en el que el Profeta, cuando envió a Abu Musa a Yemen, mandó tras él a Muʿadh ibn Yabal […] [[k:«No me siento hasta que sea matado: dictamen de Dios y de Su Mensajero»]] —tres veces—, y mandó que lo mataran; lo recogió Muslim y otros. Y mencionó Abu Yusuf de Abu Hanifa que al apóstata se le ofrece el islam: si se hace musulmán, [bien], y si no, se le mata en el acto, salvo que pida plazo; si lo pide, se le dan tres días; y lo conocido de él y de sus compañeros es que no se mata hasta pedirle el arrepentimiento; el zindiq y el apóstata son iguales para ellos. Y dijo Malik: [[k:«se mata a los zanadiqa y no se les pide el arrepentimiento».]]",
      "Y discreparon sobre la apóstata: dijeron Malik, al-Awzaʿi, al-Shafiʿi y al-Layth ibn Saʿd: [[k:se la mata como se mata al apóstata, igual;]] y su prueba es el sentido aparente del hadiz «quien cambie su religión, matadlo», y «quien» sirve para el varón y la mujer. Y dijeron al-Thawri y Abu Hanifa y sus compañeros: [[a:no se mata a la apóstata;]] y es dicho de Ibn Shubruma, y a ello fue Ibn ʿUlayya, y es dicho de ʿAta y al-Hasan. Y argumentaron que Ibn Abbas transmitió del Profeta «quien cambie su religión, matadlo», [[a:y luego Ibn Abbas no mató a la apóstata, y quien transmite un hadiz sabe mejor su interpretación;]] y se transmite lo mismo de ʿAli; y el Profeta prohibió matar a las mujeres y a los niños. Y los primeros argumentaron con el dicho: «No es lícita la sangre de un musulmán salvo por una de tres: incredulidad tras la fe…»: [[k:abarca a todo el que cometa incredulidad tras su fe, y es lo más válido.]]"],
  prueba="Al-Qurtubi (m. 671 H) recoge en su comentario a 2:217 el abanico de posiciones de los sabios sobre el apóstata: la mayoría lo mata tras pedirle el arrepentimiento (plazo de una hora a tres días; al-Hasan, hasta cien veces); algunos lo matan sin pedírselo (el Mayishun; al-Shafiʿi en uno de sus dos dichos; Tawus; ʿUbayd ibn ʿUmayr); los zanadiqa se matan sin arrepentimiento (Malik); y sobre la mujer, Malik, al-Awzaʿi, al-Shafiʿi y al-Layth la matan, al-Thawri y Abu Hanifa no. Concluye que el hadiz de las tres causas «abarca a todo el que cometa incredulidad tras su fe, y es lo más válido».",
  ojo="La pena aparece como fondo común, pero con muchas variantes: plazo (de una hora a cien veces), petición de arrepentimiento, mujeres, zanadiqa, dhimmies. Y el argumento hanafí («Ibn Abbas, que transmitió el hadiz, no mató a la apóstata») parte del mismo Ibn Abbas de AP01. Es un comentario coránico: el versículo 2:217 en sí solo dice que las obras del apóstata que muere en su incredulidad «se pierden»; la pena sale de los hadices. Texto web de KSU, sin paginación impresa.", uso=USO),

 dict(id="AP20", key="TB386", tag="310 H · al-Tabari sobre 3:86 · y Nasaʾi 4068", specs=["AP-tb386", "AP-ns4068"],
  title="Contra-evidencia: un ansari que apostató y se unió a los idólatras pregunta si hay arrepentimiento; desciende 3:86–89 y se hace musulmán (Ibn Abbas, vía ʿIkrima: al-Tabari y Nasaʾi)",
  ref="al-Tabari, Yamiʿ al-bayan, sobre el Corán 3:86; y al-Nasaʾi, Sunan, Kitab tahrim al-dam, «Bab tawbat al-murtadd», n.º 4068",
  ar_ref="تفسير الطبري، آل عمران ٨٦ · سنن النسائي ٤٠٦٨", site=QT + "; " + HU, url="https://quran-tafsir.net/tabary/sura3-aya86.html · https://hadithunlocked.com/nasai:4068",
  es=["Discreparon los exegetas sobre a quién se refiere este versículo y sobre quién fue revelado; dijo un grupo: [[k:fue revelado sobre al-Harith ibn Suwayd al-Ansari, que era musulmán y apostató tras su islam.]] Mención de quien lo dijo: me contó Muhammad ibn ʿAbd Allah ibn Baziʿ al-Basri, dijo: nos contó Yazid ibn Zurayʿ, dijo: nos contó Dawud ibn Abi Hind, de ʿIkrima, de Ibn Abbas, que dijo: [[k:Había un hombre de los ansares que se hizo musulmán, luego apostató y se unió a la idolatría, luego se arrepintió]], y envió a su pueblo [a decir]: «Preguntad al Mensajero de Dios ﷺ: [[k:¿hay para mí arrepentimiento?]]» Dijo: y descendió: {¿Cómo guiará Dios a un pueblo que renegó tras haber creído…?} hasta {…salvo los que se arrepientan después de eso y obren bien; Dios es perdonador, misericordioso}; y [[k:su pueblo envió por él [el versículo], y se hizo musulmán.]]",
      "Nos informó Muhammad ibn ʿAbd Allah ibn Baziʿ, dijo: nos contó Yazid —y es Ibn Zurayʿ—, dijo: nos informó Dawud, de ʿIkrima, de Ibn Abbas, que dijo: [[k:Había un hombre de los ansares que se hizo musulmán, luego apostató y se unió a la idolatría,]] luego se arrepintió y envió a su pueblo [a decir]: «Preguntad por mí al Mensajero de Dios ﷺ: [[k:¿hay para mí arrepentimiento?]]» Vino su pueblo al Mensajero de Dios ﷺ y dijeron: «Fulano se ha arrepentido y nos ha mandado preguntarte si tiene arrepentimiento»; y descendió {¿Cómo guiará Dios a un pueblo que renegó tras creer?} hasta {perdonador, misericordioso}; [[k:y [el Profeta] envió por él, y se hizo musulmán.]]"],
  prueba="Contra-evidencia directa en las fuentes tempranas: el hadiz de Ibn Abbas (Nasaʾi 4068; al-Tabari 3:86) cuenta que un ansari que apostató y se unió a los idólatras preguntó si tenía arrepentimiento; desciende 3:86–89, y el hombre se hace musulmán de nuevo. No es ejecutado.",
  ojo="Es del mismo Ibn Abbas, por el mismo ʿIkrima, que el hadiz «quien cambie su religión, matadlo» (AP01). Al-Tabari recoge en la misma página otras versiones (Mujahid, al-Suddi) que no se ven en la captura. La página de Nasaʾi califica la cadena «ṣaḥīḥ» (ʿAli Zaʾi). El caso es de un hombre que se retracta antes de que se actúe contra él; no equivale a decir que un apóstata no sea condenado si se mantiene.", uso=USO),

 dict(id="AP21", key="TB4137", tag="310 H · al-Tabari sobre 4:137", specs=["AP-tb4137"],
  title="al-Tabari, 4:137: ʿAli: «yo [solía] pedir al apóstata que se arrepintiera tres veces»; Ibrahim [al-Nakhaʿi]: «cada vez que apostata»; Tabari: su arrepentimiento se acepta y su islam protege su sangre",
  ref="al-Tabari, Yamiʿ al-bayan, sobre el Corán 4:137",
  ar_ref="تفسير الطبري، النساء ١٣٧", site=QT, url="https://quran-tafsir.net/tabary/sura4-aya137.html",
  es=["Y algunos fueron a que al apóstata se le pide el arrepentimiento tres veces, deduciéndolo de este versículo, y [[a:otros les discreparon.]] Mención de quien dijo «se le pide el arrepentimiento tres veces»: me contó Ibn Wakiʿ, dijo: nos contó Hafs, de Ashʿath, de al-Shaʿbi, de ʿAli —la paz sea con él—, dijo: [[k:«Yo [solía] pedir al apóstata que se arrepintiera tres veces.»]] Luego recitó este versículo: {Quienes creyeron, luego descreyeron, luego creyeron, luego descreyeron, luego aumentaron en la incredulidad…} […] Y dijeron otros: se le pide el arrepentimiento cada vez que apostata. Mención de quien lo dijo: […] de Ibrahim dijo: [[k:«Se le pide el arrepentimiento al apóstata cada vez que apostata.»]] Dijo Abu Yaʿfar [al-Tabari]: [[k:en que se establece que al apóstata se le pide el arrepentimiento la primera vez está la prueba clara de que el juicio en cada vez que apostata del islam es el juicio de la primera: que su arrepentimiento es aceptado y que su islam protege su sangre]]…"],
  prueba="Al-Tabari (m. 310 H) recoge, a propósito de 4:137, que ʿAli «pedía al apóstata que se arrepintiera tres veces» (por al-Shaʿbi) y que Ibrahim al-Nakhaʿi decía «cada vez que apostata», y concluye que, en cada apostasía, el arrepentimiento se acepta y el islam protege su sangre.",
  ojo="Al-Tabari no discute aquí la pena en sí, sino la repetición. Pero su conclusión (el arrepentimiento se acepta y protege la sangre) implica que la ejecución solo procede si el apóstata se niega a volver. Las cadenas las da Ibn Wakiʿ y otros: no las he evaluado. Peters y De Vries (AP22) citan una «opinión aislada» de al-Nakhaʿi de pedirle arrepentimiento siempre (yustatab abadan). Esa formulación existe: la leí después en ʿAbd al-Razzaq 18775 (AP28) y la cita Ibn Qudama (AP41); lo que trae al-Tabari («cada vez que apostata») es otra formulación del mismo personaje, y no sé si expresan una doctrina o dos.", uso=USO),

 dict(id="AP22", key="PDV", tag="1976-77 · Peters y De Vries, «Apostasy in Islam»", specs=["AP-pdv5", "AP-pdv14"], secondary=True, lang="inglés (artículo académico en PDF)", trnote="Traducción propia del inglés. ",
  title="Peters y De Vries: «La pena establecida para la apostasía es la pena de muerte»; los hanafíes y shafiʿíes discuten que sea hadd; las mujeres, encarceladas; y los modernistas: solo el apóstata hostil",
  ref="Rudolph Peters y Gert J. J. De Vries, «Apostasy in Islam», Die Welt des Islams 17 (1976–77), pp. 5, 14 y 15",
  ar_ref="Peters y De Vries 1976-77, pp. 5, 14-15", site="pure.uva.nl (PDF del artículo; paginación impresa de la revista)", url="https://pure.uva.nl/ws/files/1472322/95409_apostasy_in_islam.pdf",
  es=["1.2 Las consecuencias legales de la apostasía. Derecho penal. [[k:La pena establecida para la apostasía es la pena de muerte.]] [[a:La opinión de que esta pena constituye un hadd o «ordenanza restrictiva» (la pena fija para los delitos contra la religión prohibidos o sancionados con castigo en el Corán) es discutida por los juristas hanafíes y shafiʿíes.]] La teoría hanafí excluye algunas categorías de la pena capital: aunque aptas para realizar un acto válido de ridda, no afrontarán su consecuencia última: (a) [[a:Las mujeres son «mantenidas como rehenes» en su lugar.]] Se las golpeará cada tres días para lograr que vuelvan al islam. Para justificar esta excepción, los eruditos hanafíes aducen una tradición según la cual el Profeta desaprobó la muerte de mujeres. También se argumentó que, por su disposición física, difícilmente cabría esperar que la apóstata supusiera una amenaza para el Estado islámico (la ratio, según la escuela hanafí, de la ejecución de los apóstatas). Finalmente, la sumisión de la mujer a su marido se consideró excluyente de un juicio plenamente independiente, y [la hace] así no plenamente responsable.",
      "Aunque la apostasía ya no cae bajo el derecho penal, la cuestión de si el apóstata debe ser muerto sigue debatiéndose en los círculos islámicos. Los modernistas sostienen que [[k:el apóstata no puede ser muerto por la mera razón de su apostasía.]] Esto solo debería hacerse si también es un peligro para el Estado islámico. Aducen los siguientes argumentos: [[a:ningún versículo del Corán prescribe la pena capital para el apóstata en cuanto apóstata;]] por el contrario, versículos como 2:218 y 3:86-97 prevén claramente una muerte natural para el apóstata. Además, 4:89 y 90 […] ofrecen prueba de que solo el apóstata peligroso y agresivo puede ser muerto. Otro argumento es que la pena capital por apostasía se funda en dos tradiciones (véase nota 12) contrarias a las normas coránicas explícitas de 4:89 y 90. Existe una controversia muy debatida sobre si una tradición puede abrogar una norma coránica. Si en este caso estas tradiciones pueden abrogar la norma coránica es aún más",
      "dudoso, pues pertenecen a la categoría de tradiciones que dependen de una sola autoridad (khabar al-ahad) y no eran ampliamente conocidas entre los Compañeros del Profeta. Así, incluso si se aceptara la autenticidad de estas tradiciones, no pueden contradecir al Corán. Por tanto, [[k:deben interpretarse como referidas solo a los apóstatas hostiles y combatientes.]]",
      "Un alegato muy detallado contra la pena capital para el apóstata fue presentado por ʿAbd al-Mutaʿali al-Saʿidi en su libro «al-Hurriyya al-diniyya fi l-islam» [La libertad religiosa en el islam]. Además de los argumentos citados, al-Saʿidi remite a [[k:una opinión aislada de Ibrahim al-Nakhaʿi (m. 95 o 96 H) de que al apóstata se le debe pedir siempre que se arrepienta (an yustatab abadan)]], de lo cual puede inferirse que no puede ser muerto."],
  prueba="Un estudio académico clásico (1976-77) afirma sin rodeos que «la pena establecida para la apostasía es la pena de muerte» en la doctrina clásica, y recoge a la vez las excepciones (mujeres, para los hanafíes; que sea hadd, para hanafíes y shafiʿíes) y los argumentos modernos en contra. Sirve para situar la doctrina: es la general, con salvedades.",
  ojo="Es un estudio sobre la doctrina clásica, escrito en 1976-77: sus afirmaciones son de los autores, no una fuente medieval. Los «modernistas» (p. 14) son ʿAbduh, Rida, Shaltut y otros (nota 37): lectura moderna, no clásica; el argumento «solo el apóstata hostil» no es el de la escuela clásica. La «opinión aislada» de al-Nakhaʿi la toman de al-Saʿidi, que a su vez remite a Ibn Hazm y a Ibn Qudama; la formulación «yustatab abadan» la comprobé yo en ʿAbd al-Razzaq 18775 (AP28) y en Ibn Qudama (AP41); en Ibn Hazm no la he leído.", uso=USO),

 dict(id="AP23", key="IAS3", tag="Mujeres · Ibn Abi Shayba 30936, 30946, 30944 y 30940", specs=["AP-ias6", "AP-ias7", "AP-ias8", "AP-ias9"],
  title="Ibn Abi Shayba, «De la apóstata: qué se hace con ella»: Ibn Abbas: «no se mata a las mujeres si apostatan»; al-Hasan: se las encarcela; Ibrahim [al-Nakhaʿi]: «se la mata» / «se le pide arrepentimiento y, si no, se la mata»",
  ref="Ibn Abi Shayba, al-Musannaf (ed. al-Shathri), «Fi l-murtadda ma yuṣnaʿ biha», vol. 16 pp. 46–48, n.º 30936, 30946, 30944 y 30940",
  ar_ref="مصنف ابن أبي شيبة ٣٠٩٣٦ وما بعده", site=SH, url="https://shamela.ws/book/333/35495 · https://shamela.ws/book/333/35505 · https://shamela.ws/book/333/35503 · https://shamela.ws/book/333/35499",
  es=["30936 - Nos contó Abu Bakr, dijo: nos contó ʿAbd al-Rahim ibn Sulayman y Wakiʿ, de Abu Hanifa, de ʿAsim, de Abu Razin, de Ibn Abbas, que dijo: [[k:«No se mata a las mujeres si apostatan del islam,]] sino que se las encarcela, se las llama al islam [y se las obliga a él].»",
      "[[a:(Nota del editor:) Débil, por la debilidad de ʿAsim en [su transmisión de] Abu Razin.]]",
      "30946 - Nos contó Abu Bakr, dijo: nos contó ʿAbd al-Samad, de Hisham, de Hammad, de Ibrahim, que dijo: [[k:«Se la mata.»]]",
      "[…] sobre la mujer que apostata del islam, dijo: [[k:«Se le pide el arrepentimiento; si se arrepiente, [bien], y si no, se la mata.»]]",
      "[…] de al-Hasan, sobre la mujer que apostata del islam, dijo: [[a:«No se la mata; se la encarcela.»]]"],
  prueba="Ibn Abi Shayba (m. 235 H) reúne, en el capítulo sobre la apóstata, las posturas tempranas: Ibn Abbas (por Abu Hanifa, ʿAsim y Abu Razin): no se las mata, se las encarcela y se las llama al islam; al-Hasan: se las encarcela; Ibrahim al-Nakhaʿi: se las mata (30946) o se les pide el arrepentimiento y, si no, se las mata (30944). Es la raíz de la diferencia entre los hanafíes y las demás escuelas.",
  ojo="El hadiz de Ibn Abbas que usan los hanafíes lo califica el editor de «débil por la debilidad de ʿAsim». Y Ibn Abbas es el mismo que transmite «quien cambie su religión, matadlo» (AP01): al-Qurtubi (AP19) cuenta que los hanafíes argumentan que él, siendo el transmisor, no mataba a la apóstata (otra versión, Bayhaqi/Daraqutni, la cuenta mis agentes con cadenas calificadas de débiles; no las he leído). Ibrahim aparece en las dos direcciones. Texto de Shamela, no de la edición impresa. La misma discusión sobre las mujeres, leída después en otros autores: Mudawwana 2/55 (AP35), Ibn Qudama 9/3 (AP39), Ibn Rushd 16/392 (AP45) y Bidaya 4/242 (AP46).", uso=USO),
]
